<?php
namespace App\Services\Branding;use App\Contracts\ProtectedMediaStorage;use Illuminate\Http\UploadedFile;use Illuminate\Validation\ValidationException;
class WatermarkLogoStorage{public function __construct(private ProtectedMediaStorage$s){}public function store(UploadedFile$f,int$id):array{$bytes=@file_get_contents($f->getRealPath());$im=$bytes!==false?@imagecreatefromstring($bytes):false;if(!$im)throw ValidationException::withMessages(['logo'=>'The selected image is corrupted or invalid.']);$w=imagesx($im);$h=imagesy($im);imagedestroy($im);if($w<1||$h<1||$w*$h>40000000)throw ValidationException::withMessages(['logo'=>'The selected image dimensions are not supported.']);$mime=(new \finfo(FILEINFO_MIME_TYPE))->buffer($bytes);$map=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'];if(!isset($map[$mime]))throw ValidationException::withMessages(['logo'=>'The selected image format is not supported.']);$key=$this->s->putFile('branding/watermarks/users/'.$id,$f,$map[$mime]);return['logo_disk'=>$this->s->disk(),'logo_object_key'=>$key,'logo_mime_type'=>$mime,'logo_size_bytes'=>$this->s->size($key),'logo_checksum'=>$this->s->checksum($key)];}public function delete(?string$k):void{if($k&&$this->s->exists($k))$this->s->delete($k);}}
